def generate(rng, n):
    if n <= 0:
        return [None]
    vals = [rng.randint(1, 1000) for _ in range(n)]
    head = ListNode(vals[0])
    curr = head
    for v in vals[1:]:
        curr.next = ListNode(v)
        curr = curr.next
    return [head]

def generate_worst(rng, n):
    return generate(rng, n)
